properties.query:
let smb_events = SecurityEvent | where EventID == 5140 and ShareName contains "\\" | summarize smb_time=min(TimeGenerated) by TargetUserName, Computer;
let lsa_events = SecurityEvent | where EventID == 4663 and ObjectName has_any ("lsa", "lsa secrets") | summarize lsa_time=min(TimeGenerated) by TargetUserName, Computer;
smb_events | join kind=inner lsa_events on TargetUserName | where lsa_time - smb_time between (0min .. 120min)
